insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('136', 'Prioritization Discipline', '2026-08-03 07:22:06.549529+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Name your single most important priority for the next 90 days.", "List every opportunity you''re currently pursuing and mark which ones don''t serve that priority.", "Create a simple ''not right now'' list for good opportunities that aren''t a current fit."]', '["all"]', 'INT-136', '137', '[{"name": "Not-Right-Now List", "brief": "Park good but off-priority opportunities somewhere visible, instead of either chasing them immediately or losing them entirely."}, {"name": "Single Priority Filter", "brief": "Test every new opportunity against the one thing that matters most right now, before considering it further."}]', '["RC-1067", "RC-1068", "RC-1069", "RC-1071", "RC-1070", "RC-1072"]', '["RC-1070", "RC-1072"]', 'Opportunity Evaluation', '[3, 4, 5]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('137', 'Comparative Opportunity Analysis', '2026-08-03 07:22:06.549529+00', '["evidence_based"]', '[]', '["List every opportunity currently on the table for you in one place, today.", "Score each one against the same 3-4 criteria (fit, cost, upside, urgency).", "Set a decision deadline for each one so none expire by default."]', '["all"]', 'INT-137', '138', '[{"name": "Opportunity Comparison Board", "brief": "Track all live opportunities in one place with shared criteria, so decisions are made by comparison rather than in isolation."}, {"name": "Weighted Decision Matrix", "brief": "Score competing opportunities against the same weighted criteria (strategic fit, cost, upside, urgency) to reduce recency bias."}]', '["RC-1073", "RC-1074", "RC-1075", "RC-1076", "RC-1077", "RC-1078"]', '["RC-1077", "RC-1078"]', 'Opportunity Evaluation', '[3, 4, 5]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('138', 'Planning Cadence', '2026-08-03 07:29:58.591693+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Schedule your next planning session on the calendar right now, before this conversation ends.", "Write down, even roughly, where you want the business to be in 6 months.", "Set a recurring monthly or quarterly reminder to review progress against that plan."]', '["all"]', 'INT-138', '139', '[{"name": "Quarterly Planning Rhythm", "brief": "Set a recurring cadence (e.g. quarterly) to step back, review progress, and set the next period''s priorities."}, {"name": "Plan-vs-Actual Review", "brief": "Compare what was planned against what actually happened at each check-in, to build a real feedback loop into planning."}]', '["RC-1079", "RC-1080", "RC-1081", "RC-1083", "RC-1082", "RC-1084", "RC-1085"]', '["RC-1082", "RC-1084", "RC-1085"]', 'Business Planning', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('139', 'Goal Structuring', '2026-08-03 07:29:58.591693+00', '["evidence_based"]', '[]', '["Rewrite your top goal into one specific, measurable, time-bound sentence.", "List the 3 things that must happen this week to move toward that goal.", "Pick one metric you''ll check weekly to know if you''re on track."]', '["all"]', 'INT-139', '140', '[{"name": "OKR-Style Goal Breakdown", "brief": "Break a big annual or quarterly goal into specific, measurable objectives with a clear deadline and progress metric."}, {"name": "Goal-to-Weekly-Action Chain", "brief": "Explicitly connect this week''s tasks back to the quarterly or annual goal they''re meant to serve."}]', '["RC-1086", "RC-1087", "RC-1088", "RC-1090", "RC-1089", "RC-1091"]', '["RC-1089", "RC-1091"]', 'Business Planning', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('140', 'Scenario Planning', '2026-08-03 07:29:58.591693+00', '["evidence_based"]', '[]', '["Write down the single biggest assumption your current plan depends on.", "Sketch a rough backup plan for what you''d do if that assumption proved false.", "Define one specific, measurable trigger point that would tell you it''s time to change course."]', '["all"]', 'INT-140', '141', '[{"name": "Key Assumption Audit", "brief": "Name the 2-3 assumptions the current plan depends on most, and pressure-test what happens if each is wrong."}, {"name": "Trigger-Point Planning", "brief": "Pre-define specific signals that would mean the current plan needs to change, rather than deciding in the moment under pressure."}]', '["RC-1092", "RC-1093", "RC-1094", "RC-1095", "RC-1096", "RC-1097"]', '["RC-1096", "RC-1097"]', 'Business Planning', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('141', 'Risk Discovery', '2026-08-03 08:09:29.50101+00', '["evidence_based"]', '[]', '["Block time this week to list out risks across 5 domains: financial, legal, operational, market, and team.", "Ask 2-3 team members what they think could seriously hurt the business.", "Write down the risk you only discovered after it already caused a problem, and what would have surfaced it earlier."]', '["all"]', 'INT-141', '142', '[{"name": "Risk Domain Sweep", "brief": "Systematically review each major domain (financial, legal, operational, market, team) for risks rather than relying on whatever comes to mind."}, {"name": "Team Risk Input Session", "brief": "Ask people closest to daily operations what risks they see that the founder might be missing."}]', '["RC-1098", "RC-1099", "RC-1100", "RC-1101", "RC-1102", "RC-1103", "RC-1104"]', '["RC-1102", "RC-1103", "RC-1104"]', 'Risk Identification', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('142', 'Risk Mitigation Planning', '2026-08-03 08:09:29.50101+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Pick your single most concerning known risk and write one small action you could take on it this week.", "Set a recurring monthly reminder to review your risk list.", "Identify what minimal resource (time or money) would be needed to meaningfully reduce your top risk."]', '["all"]', 'INT-142', '143', '[{"name": "Risk Mitigation Action List", "brief": "Turn each identified risk into one small, specific first action rather than treating mitigation as an all-or-nothing project."}, {"name": "Risk Review Cadence", "brief": "Set a recurring check-in to revisit known risks and see whether they''ve grown more or less urgent."}]', '["RC-1105", "RC-1106", "RC-1107", "RC-1108", "RC-1109", "RC-1110"]', '["RC-1109", "RC-1110"]', 'Risk Identification', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('143', 'Concentration Risk Management', '2026-08-03 08:09:29.50101+00', '["evidence_based"]', '[]', '["Calculate what percentage of revenue comes from your top customer and top 3 customers combined.", "Identify the one team member whose sudden absence would hurt most, and document what only they know.", "Name one small step you could take this month to reduce dependency on your top single point of failure."]', '["all"]', 'INT-143', '144', '[{"name": "Single Point of Failure Audit", "brief": "Systematically check revenue, suppliers, key people, and acquisition channels for dangerous concentration."}, {"name": "Diversification Roadmap", "brief": "Set a gradual, realistic plan to reduce dependency on any one customer, supplier, person, or channel."}]', '["RC-1111", "RC-1112", "RC-1113", "RC-1114", "RC-1115", "RC-1116"]', '["RC-1115", "RC-1116"]', 'Risk Identification', '[3, 4, 5]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
