insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('146', 'Differentiation Clarity', '2026-08-03 10:51:37.049854+00', '["evidence_based"]', '[]', '["Ask your last 5 customers directly why they chose you over an alternative.", "Write your differentiation claim in one sentence with no vague words like ''better'' or ''quality.''", "Identify how easily a competitor could copy your main claimed difference, and note what would make it harder to copy."]', '["all"]', 'INT-146', '147', '[{"name": "Specific Differentiation Test", "brief": "Push past vague claims (''better,'' ''quality'') to a specific, provable point of difference a customer could actually verify."}, {"name": "Customer-Validated Differentiation", "brief": "Directly ask customers why they chose you over alternatives, rather than assuming the reason."}]', '["RC-1129", "RC-1130", "RC-1131", "RC-1132", "RC-1133", "RC-1134"]', '["RC-1133", "RC-1134"]', 'Competitive Awareness', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
