insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('150', 'Plan Communication', '2026-08-03 11:13:13.816281+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Write your current plan or top priorities on a single page and share it with your team this week.", "Ask 2-3 team members what they believe the top priority is, and compare to your own answer.", "Set a habit of announcing plan changes to the team as soon as they happen, not after the fact."]', '["all"]', 'INT-150', '151', '[{"name": "One-Page Plan Share", "brief": "Turn the plan into a simple one-page document the whole team can see and refer back to."}, {"name": "Priority Alignment Check", "brief": "Regularly verify that the team''s understanding of top priorities matches the founder''s."}]', '["RC-1153", "RC-1154", "RC-1156", "RC-1157", "RC-1155", "RC-1158"]', '["RC-1155", "RC-1158"]', 'Business Planning', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
