insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('157', 'Proposal Preparation', '2026-08-03 13:30:28.463423+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Build one reusable proposal template with a section that gets customized to each prospect''s specific discussed needs.", "Set a target turnaround time (e.g. 24-48 hours) for getting a proposal out after a conversation.", "Start tracking why each proposal is accepted or rejected, even in a simple spreadsheet."]', '["all"]', 'INT-157', '158', '[{"name": "Reusable Proposal Template", "brief": "Build a base proposal template with sections for the specific problem discussed, the proposed solution, and clear pricing options."}, {"name": "Proposal Follow-Up Cadence", "brief": "Plan a specific follow-up sequence after sending a proposal instead of waiting passively."}]', '["RC-1197", "RC-1198", "RC-1199", "RC-1200", "RC-1201", "RC-1202", "RC-1203"]', '["RC-1201", "RC-1202", "RC-1203"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('158', 'Follow-Up Cadence Design', '2026-08-03 15:50:38.299213+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Design a specific follow-up schedule (e.g. days 1, 3, 7, 14) for every new prospect.", "Write 3 different follow-up message angles so you''re not repeating the same message each time.", "Set a clear number of attempts after which you''ll stop following up with an unresponsive prospect."]', '["all"]', 'INT-158', '159', '[{"name": "Multi-Touch Follow-Up Sequence", "brief": "Design a defined cadence (e.g. day 1, 3, 7, 14, 30) with a clear stopping point, rather than following up whenever remembered."}, {"name": "Value-Add Follow-Up Rotation", "brief": "Vary each follow-up message with new value (an insight, a question, a resource) rather than repeating the same check-in."}]', '["RC-1204", "RC-1205", "RC-1206", "RC-1207", "RC-1208", "RC-1209", "RC-1210"]', '["RC-1208", "RC-1209", "RC-1210"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('159', 'Lost Deal Analysis', '2026-08-03 15:55:59.771263+00', '["evidence_based"]', '[]', '["For your last 3 lost deals, write down the specific reason each one was lost, based on real evidence not assumption.", "Ask your next lost prospect directly why they chose not to move forward.", "Start a simple log of loss reasons to spot patterns over time."]', '["all"]', 'INT-159', '160', '[{"name": "Loss Reason Categorization", "brief": "Tag every lost deal with a specific reason (price, timing, fit, competitor, no decision) rather than defaulting to ''price was too high.''"}, {"name": "Post-Mortem Prospect Follow-Up", "brief": "Directly ask lost prospects why they decided not to move forward, rather than assuming."}]', '["RC-1211", "RC-1212", "RC-1213", "RC-1214", "RC-1215", "RC-1216", "RC-1217"]', '["RC-1215", "RC-1216", "RC-1217"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('160', 'Conversion Rate Improvement', '2026-08-03 16:04:24.816392+00', '["evidence_based"]', '[]', '["Calculate your conversion rate at each stage of your sales process, not just the final lead-to-customer number.", "Identify the single stage where you lose the most prospects, and focus improvement effort there first.", "Pick one specific change to test in your sales process, and measure its effect on conversion before making further changes."]', '["all"]', 'INT-160', '161', '[{"name": "Funnel Stage Breakdown", "brief": "Track conversion rate at each individual stage of the sales process, not just the overall lead-to-customer number, to find where prospects actually drop off."}, {"name": "Conversion Testing Discipline", "brief": "Deliberately test one change at a time (pitch, pricing, process) and measure its effect on conversion, rather than changing things on gut feel."}]', '["RC-1218", "RC-1219", "RC-1220", "RC-1221", "RC-1222", "RC-1223", "RC-1224"]', '["RC-1222", "RC-1223", "RC-1224"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('161', 'Customer Relationship Management', '2026-08-03 17:27:08.35606+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Name one person (even if it''s you for now) as the owner of ongoing customer relationships.", "Set a specific check-in cadence (e.g. monthly) for your most valuable customers.", "Identify 2-3 early warning signs you''ll start tracking to catch at-risk customers before they churn."]', '["all"]', 'INT-161', '162', '[{"name": "Customer Check-In Cadence", "brief": "Set a regular, proactive rhythm for reaching out to existing customers rather than only responding when they initiate contact."}, {"name": "Early Warning Signal Tracking", "brief": "Identify and monitor specific signs (usage decline, payment delays, disengagement) that indicate a customer may be at risk."}]', '["RC-1225", "RC-1226", "RC-1227", "RC-1229", "RC-1228", "RC-1230", "RC-1231"]', '["RC-1228", "RC-1230", "RC-1231"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('162', 'Content Planning', '2026-08-03 17:40:23.046332+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Build a simple content calendar for the next 4 weeks, even if basic.", "Define 3-4 content themes or pillars that tie back to your core business message.", "Set a specific, sustainable publishing cadence (e.g. once a week) and commit to it."]', '["all"]', 'INT-162', '163', '[{"name": "Content Calendar Template", "brief": "Build a simple recurring calendar mapping out what content goes out and when, rather than relying on spontaneous motivation."}, {"name": "Content Pillar Framework", "brief": "Define 3-4 core content themes tied to the business''s key messages, so topics aren''t picked randomly."}]', '["RC-1232", "RC-1233", "RC-1234", "RC-1235", "RC-1236", "RC-1237", "RC-1238"]', '["RC-1236", "RC-1237", "RC-1238"]', 'Marketing Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('163', 'Content Creation System', '2026-08-03 17:45:07.872302+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Start a simple running list of content ideas, adding to it whenever inspiration strikes.", "Pick one reusable format or template you can apply to your next 3 pieces of content.", "Identify one part of content creation you could delegate or speed up with a tool."]', '["all"]', 'INT-163', '164', '[{"name": "Content Idea Backlog", "brief": "Maintain a running list of content ideas so creation never starts from a blank page."}, {"name": "Reusable Content Templates", "brief": "Build a small set of reusable formats (e.g. a how-to structure, a customer story structure) to speed up and standardize content creation."}]', '["RC-1239", "RC-1240", "RC-1241", "RC-1242", "RC-1243", "RC-1244", "RC-1245"]', '["RC-1243", "RC-1244", "RC-1245"]', 'Marketing Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('164', 'Campaign Planning', '2026-08-03 17:49:05.55514+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Before your next campaign, write a one-page brief covering goal, audience, budget, timeline, and channel.", "Set a specific, written budget for the campaign before it launches.", "Choose your channel based on where your specific target audience spends time, not just your usual default."]', '["all"]', 'INT-164', '165', '[{"name": "Campaign Brief Template", "brief": "Define goal, target audience, budget, timeline, and channel before launching any campaign, rather than figuring it out along the way."}, {"name": "Channel Fit Assessment", "brief": "Choose a campaign channel based on where the specific target audience actually is, not just habit."}]', '["RC-1246", "RC-1247", "RC-1248", "RC-1250", "RC-1249", "RC-1251", "RC-1252"]', '["RC-1249", "RC-1251", "RC-1252"]', 'Marketing Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('165', 'Campaign Analysis', '2026-08-03 17:53:33.186593+00', '["evidence_based"]', '[]', '["For your last campaign, compare the actual results directly against the goal you set beforehand.", "Identify one specific element (message, channel, timing) that most influenced the outcome.", "Start a simple log of campaign learnings that you''ll check before planning your next campaign."]', '["all"]', 'INT-165', '166', '[{"name": "Goal-vs-Actual Campaign Review", "brief": "Compare campaign results directly against the original goal set before launch, not just general performance metrics."}, {"name": "Campaign Learnings Log", "brief": "Document specific learnings from each campaign (what worked, what didn''t) in one place that gets referenced before planning the next one."}]', '["RC-1253", "RC-1254", "RC-1255", "RC-1256", "RC-1257", "RC-1258", "RC-1259"]', '["RC-1257", "RC-1258", "RC-1259"]', 'Marketing Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
