insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('171', 'Financial Reporting Practice', '2026-08-03 18:59:41.477496+00', '["evidence_based"]', '[]', '["Define the standard set of reports your business will produce every month.", "Set a specific recurring date each month to review financial reports.", "Connect that review to a specific decision or action each time, not just passive reading."]', '["all"]', 'INT-171', '173', '[{"name": "Monthly Reporting Cadence", "brief": "Establish a standard set of reports (P&L, cash flow, balance sheet) produced and reviewed on a consistent monthly schedule."}, {"name": "Reports-to-Decisions Link", "brief": "Tie financial report review directly to a recurring decision-making meeting, so reports actually inform action."}]', '["RC-1295", "RC-1296", "RC-1297", "RC-1298", "RC-1299", "RC-1300", "RC-1301"]', '["RC-1299", "RC-1300", "RC-1301"]', 'Financial Management', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('172', 'Early-Stage Onboarding', '2026-08-03 19:03:14.414014+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Write a simple first-week plan for your next hire, covering what they''ll do each day.", "Document what success looks like in the role, even briefly, before they start.", "Schedule specific check-in points at 30, 60, and 90 days."]', '["all"]', 'INT-172', '174', '[{"name": "First-Week Onboarding Plan", "brief": "Build a simple structured plan for a new hire''s first week, even for a founder''s very first employee, rather than leaving it improvised."}, {"name": "30-60-90 Day Check-In Structure", "brief": "Schedule specific check-in points in the first 90 days to catch issues early and support ramp-up."}]', '["RC-1302", "RC-1303", "RC-1304", "RC-1305", "RC-1306", "RC-1307", "RC-1308"]', '["RC-1306", "RC-1307", "RC-1308"]', 'Team & Leadership', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
