insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('176', 'Lead Prioritization', '2026-08-04 05:14:16.566521+00', '["evidence_based", "minimum_effective_dose"]', '[]', '["Define 3-4 simple criteria to score any lead against (e.g. budget, urgency, fit).", "Sort your current active leads into hot/warm/cold tiers based on those criteria.", "Block time each day specifically for your hottest-tier leads first."]', '["all"]', 'INT-176', '178', '[{"name": "Simple Lead Scoring Model", "brief": "Score leads on a few key factors (budget fit, urgency, decision authority) to rank them consistently rather than by gut feel."}, {"name": "Hot/Warm/Cold Tiering", "brief": "Sort leads into three simple tiers to instantly see which deserve immediate attention."}]', '["RC-1330", "RC-1331", "RC-1332", "RC-1334", "RC-1333", "RC-1335", "RC-1336"]', '["RC-1333", "RC-1335", "RC-1336"]', 'Sales Execution', '[2, 3, 4]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
