insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('191', 'Follow-Up Performance Measurement', '2026-08-04 10:33:39.286665+00', '["evidence_based"]', '[]', '["Start tracking which follow-up attempt (1st, 2nd, 3rd, etc.) gets a response for your next 10 prospects.", "Test two different follow-up timings and compare results.", "Set a monthly check-in to review your follow-up response rates and adjust your approach."]', '["all"]', 'INT-191', '193', '[{"name": "Response Rate by Attempt Tracking", "brief": "Track which follow-up attempt number actually generates responses, to focus effort where it works."}, {"name": "Follow-Up Timing Test", "brief": "Compare different intervals between follow-ups to identify which timing produces better results."}]', '["RC-1435", "RC-1436", "RC-1437", "RC-1438", "RC-1439", "RC-1440", "RC-1441"]', '["RC-1439", "RC-1440", "RC-1441"]', 'Sales Execution', '[3, 4, 5]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
