insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('216', 'Campaign ROI Calculation', '2026-08-04 15:25:53.335211+00', '["evidence_based"]', '[]', '["Pull your last campaign''s total spend and divide it by the number of leads or sales it generated.", "Start tagging new deals with which campaign, if any, they came from.", "Compare cost-per-result across your last few campaigns to see which was actually most efficient."]', '["all"]', 'INT-216', '218', '[{"name": "Cost-Per-Result Formula", "brief": "Divide total campaign spend by number of leads or sales generated to get a concrete cost-per-result number."}, {"name": "Campaign Revenue Tagging", "brief": "Tag deals or sales with which campaign they came from so revenue can be traced back to cost."}]', '["RC-1610", "RC-1611", "RC-1612", "RC-1613", "RC-1614", "RC-1615", "RC-1616"]', '["RC-1614", "RC-1615", "RC-1616"]', 'Marketing Execution', '[1, 2, 3]', '2026-08-16 04:47:55.278096+00') on conflict do nothing;
