insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('227', 'Runway-Informed Decision-Making', '2026-08-05 04:55:12.398114+00', '["evidence_based"]', '[]', '["Before your next hiring or spending decision, calculate what your runway looks like with that cost added.", "Add a runway-impact check as a standard step in your decision process for commitments above a certain size.", "Review your last few small commitments together and see their combined effect on runway."]', '["all"]', 'INT-227', '229', '[{"name": "Runway Impact Check", "brief": "Before any hire or major expense, calculate the new runway number with that cost included."}, {"name": "Standing Runway Question", "brief": "Make ''what does this do to our runway'' a standard question for every significant spending decision."}]', '["RC-1687", "RC-1688", "RC-1689", "RC-1690", "RC-1691", "RC-1692", "RC-1693"]', '["RC-1691", "RC-1692", "RC-1693"]', 'Financial Management', '[4, 5, 6]', '2026-08-16 04:47:55.278096+00') on conflict do nothing;
