insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('253', 'Priority-Linked Performance Tracking', '2026-08-06 04:29:00.597438+00', '["evidence_based"]', '[]', '["List your top current business priorities.", "For each team member, connect their individual goals to those priorities explicitly.", "Next time priorities shift, update what you''re tracking for performance to match."]', '["all"]', 'INT-253', '255', '[{"name": "Priority-to-Person Mapping", "brief": "For each team member, explicitly connect their individual goals to the current top business priorities."}, {"name": "Performance Criteria Refresh", "brief": "Revisit what you''re tracking for performance whenever business priorities shift."}]', '["RC-1871", "RC-1872", "RC-1873", "RC-1874", "RC-1875", "RC-1876", "RC-1877"]', '["RC-1875", "RC-1876", "RC-1877"]', 'Team & Leadership', '[1, 2]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('254', 'Team-Wide Performance Comparison', '2026-08-06 04:36:46.024494+00', '["evidence_based"]', '[]', '["List out each team member and a quick note on how they''re doing.", "Compare the list to identify who stands out as excelling or struggling.", "Use that comparison to decide where to focus support or consider next steps for growth."]', '["all"]', 'INT-254', '256', '[{"name": "Team Performance Snapshot", "brief": "Periodically step back and compare all team members side by side to spot who needs support or is ready for more."}, {"name": "Comparative Decision Check", "brief": "Before decisions like promotions, deliberately look at performance across the whole team rather than in isolation."}]', '["RC-1878", "RC-1879", "RC-1880", "RC-1881", "RC-1882", "RC-1883", "RC-1884"]', '["RC-1882", "RC-1883", "RC-1884"]', 'Team & Leadership', '[1, 2]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('255', 'Centralized SOP Repository', '2026-08-06 04:40:36.514808+00', '["evidence_based"]', '[]', '["Pick one tool or folder to be the single home for all SOPs.", "Move every existing SOP into that one place.", "Tell your team where it is and make it the default answer whenever a process question comes up."]', '["all"]', 'INT-255', '257', '[{"name": "Single Source of Truth", "brief": "Pick one tool or folder to be the designated home for all SOPs, and move everything there."}, {"name": "Consistent Naming System", "brief": "Use a simple, consistent naming and folder structure so procedures are easy to find."}]', '["RC-1885", "RC-1886", "RC-1887", "RC-1888", "RC-1889", "RC-1890", "RC-1891"]', '["RC-1889", "RC-1890", "RC-1891"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('256', 'SOP Compliance Verification', '2026-08-06 04:47:32.11853+00', '["evidence_based"]', '[]', '["Pick one written SOP and spot-check whether recent work actually followed it.", "If you find a deviation, ask the person why before assuming it was a mistake.", "Set a recurring reminder to periodically check SOP compliance going forward."]', '["all"]', 'INT-256', '258', '[{"name": "Periodic Spot-Check", "brief": "Occasionally compare actual work against the written SOP to confirm it is being followed."}, {"name": "Deviation Investigation", "brief": "When you notice a deviation from an SOP, ask why — it may mean the SOP needs updating, not just enforcing."}]', '["RC-1892", "RC-1893", "RC-1894", "RC-1895", "RC-1896", "RC-1897", "RC-1898"]', '["RC-1896", "RC-1897", "RC-1898"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('257', 'SOP Prioritization', '2026-08-06 04:51:10.759467+00', '["evidence_based"]', '[]', '["List every process that currently has no SOP.", "Rank that list by how frequently it happens and how risky a mistake would be.", "Document the top 1-2 highest-priority processes first."]', '["all"]', 'INT-257', '259', '[{"name": "Frequency-and-Risk Ranking", "brief": "List your undocumented processes and rank them by how often they happen and how costly a mistake would be."}, {"name": "Documentation Backlog List", "brief": "Keep a running list of processes still needing an SOP, so priority isn''t decided randomly."}]', '["RC-1899", "RC-1900", "RC-1901", "RC-1902", "RC-1903", "RC-1904", "RC-1905"]', '["RC-1903", "RC-1904", "RC-1905"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('259', 'Consistent Policy Enforcement', '2026-08-06 05:01:25.358183+00', '["evidence_based"]', '[]', '["Review your policies and think honestly about whether they''ve been applied consistently.", "Define clear criteria for when an exception is acceptable going forward.", "Start logging any exceptions you make so you can spot patterns over time."]', '["all"]', 'INT-259', '261', '[{"name": "Exception Criteria", "brief": "Define clear, consistent criteria for when a policy exception is acceptable, rather than deciding case by case."}, {"name": "Exception Log", "brief": "Keep a simple record of any exceptions made, so patterns of inconsistency become visible."}]', '["RC-1913", "RC-1914", "RC-1915", "RC-1916", "RC-1917", "RC-1918", "RC-1919"]', '["RC-1917", "RC-1918", "RC-1919"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('260', 'Policy Acknowledgment Process', '2026-08-06 05:05:43.867871+00', '["evidence_based"]', '[]', '["Next time you share a policy, ask for a simple written confirmation it was read.", "Start a basic list tracking who has acknowledged which policies.", "Go back and get acknowledgment from existing team members for policies they may have missed."]', '["all"]', 'INT-260', '262', '[{"name": "Simple Acknowledgment Step", "brief": "Add a quick confirmation step — even a simple reply or checkbox — whenever a policy is shared."}, {"name": "Acknowledgment Tracker", "brief": "Keep a simple record of who has confirmed reading each policy."}]', '["RC-1920", "RC-1921", "RC-1922", "RC-1923", "RC-1924", "RC-1925", "RC-1926"]', '["RC-1924", "RC-1925", "RC-1926"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('261', 'High-Risk Policy Coverage', '2026-08-06 05:10:42.400031+00', '["evidence_based"]', '[]', '["List the high-risk areas your business hasn''t documented yet — conduct, harassment, data privacy, conflicts of interest.", "Draft a short, clear policy for the highest-priority one first.", "Consider getting a quick legal review of these specific policies once drafted."]', '["all"]', 'INT-261', '263', '[{"name": "Risk Area Checklist", "brief": "Identify the specific high-risk policy areas (conduct, harassment, data privacy) most relevant to your business."}, {"name": "Basic Policy Draft", "brief": "Draft a simple, clear policy for each high-risk area, even a short one, rather than leaving it undocumented."}]', '["RC-1927", "RC-1928", "RC-1929", "RC-1930", "RC-1931", "RC-1932", "RC-1933"]', '["RC-1931", "RC-1932", "RC-1933"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('262', 'Policy Review Cadence', '2026-08-06 05:16:28.535743+00', '["evidence_based"]', '[]', '["Set a yearly reminder to review all existing policies.", "Assign someone (even yourself) as the owner responsible for keeping policies current.", "Do a first pass now checking whether any existing policy already feels outdated."]', '["all"]', 'INT-262', '264', '[{"name": "Annual Policy Review", "brief": "Set a recurring yearly check-in to review whether existing policies still fit the business and the law."}, {"name": "Policy Owner", "brief": "Assign someone responsibility for keeping policies current, even if it is the founder with a calendar reminder."}]', '["RC-1934", "RC-1935", "RC-1936", "RC-1937", "RC-1938", "RC-1939", "RC-1940"]', '["RC-1938", "RC-1939", "RC-1940"]', 'Operations & Systems', '[1, 2, 3]', '2026-08-06 05:47:10.459672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('263', 'Lead Generation Systemization', '2026-08-06 07:43:18.981802+00', '["evidence_based"]', '[]', '["Pick one lead generation channel to focus on this month.", "Set a simple weekly target for new leads.", "Block time on your calendar each week specifically for lead generation, not just when the pipeline is empty."]', '["all"]', 'INT-263', '265', '[{"name": "One-Channel Commitment", "brief": "Pick a single lead-gen channel and commit to working it consistently before spreading effort across many."}, {"name": "Weekly Lead Gen Rhythm", "brief": "Set aside a fixed block of time each week specifically for lead generation activity, regardless of pipeline status."}]', '["RC-1941", "RC-1942", "RC-1943", "RC-1944", "RC-1945", "RC-1946", "RC-1947"]', '[]', 'Sales Execution', '[1, 2, 3]', '2026-08-06 07:43:18.981802+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('264', 'Outbound Prospecting Kickstart', '2026-08-06 07:44:49.935685+00', '["evidence_based"]', '[]', '["Build a list of 10-20 specific people or companies to reach out to.", "Block 30 minutes this week for your first round of outreach.", "Track who you contacted and what happened, even in a simple spreadsheet."]', '["all"]', 'INT-264', '266', '[{"name": "Small Target List", "brief": "Build a short list of 10-20 specific potential customers to reach out to first, rather than an intimidating open-ended search."}, {"name": "Protected Outreach Time", "brief": "Block a small, recurring chunk of time each week specifically for outbound, so it stops being crowded out."}]', '["RC-1948", "RC-1949", "RC-1950", "RC-1951", "RC-1952", "RC-1953", "RC-1954"]', '[]', 'Sales Execution', '[1, 2, 3]', '2026-08-06 07:44:49.935685+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('265', 'Inbound Lead Capture Basics', '2026-08-06 10:03:13.222731+00', '["evidence_based"]', '[]', '["Add one clear way for a visitor to express interest on your website or main content.", "Set a simple, sustainable content publishing rhythm you can actually keep.", "Track whether any content or presence you have has ever produced a lead."]', '["all"]', 'INT-265', '267', '[{"name": "One Clear Call-to-Action", "brief": "Add a single, obvious way for an interested visitor to express interest — a form, a calendar link, a contact button."}, {"name": "Minimum Viable Content Cadence", "brief": "Commit to a small, sustainable publishing rhythm rather than sporadic bursts, to let inbound compound over time."}]', '["RC-1955", "RC-1956", "RC-1957", "RC-1958", "RC-1959", "RC-1960", "RC-1961"]', '[]', 'Sales Execution', '[1, 2, 3]', '2026-08-06 10:03:13.222731+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('266', 'Partnership Lead Channel', '2026-08-06 10:04:10.856672+00', '["evidence_based"]', '[]', '["List 5-10 businesses that serve your same customers without being competitors.", "Draft a short pitch for why partnering with you would benefit them.", "Reach out to one this week to start the conversation."]', '["all"]', 'INT-266', '268', '[{"name": "Complementary Business List", "brief": "Identify 5-10 businesses that serve your same target customer without competing with you directly."}, {"name": "Simple Partner Pitch", "brief": "Develop a short, clear pitch for what a partner would get out of collaborating with you."}]', '["RC-1962", "RC-1963", "RC-1964", "RC-1965", "RC-1966", "RC-1967", "RC-1968"]', '[]', 'Sales Execution', '[1, 2, 3]', '2026-08-06 10:04:10.856672+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('267', 'Paid Channel Testing', '2026-08-06 10:05:21.076541+00', '["evidence_based"]', '[]', '["Calculate roughly what you could afford to pay per lead given your deal value and conversion rate.", "Set aside a small, defined budget to test one paid channel.", "Run a small test and measure the actual cost per lead against what you calculated."]', '["all"]', 'INT-267', '269', '[{"name": "Small Budget Test", "brief": "Allocate a small, defined budget to test a single paid channel rather than committing heavily upfront."}, {"name": "Max Acceptable Cost-Per-Lead", "brief": "Calculate what you could afford to pay per lead based on your typical deal value and conversion rate, before testing."}]', '["RC-1969", "RC-1970", "RC-1971", "RC-1972", "RC-1973", "RC-1974", "RC-1975"]', '[]', 'Sales Execution', '[1, 2, 3]', '2026-08-06 10:05:21.076541+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('269', 'Lead Qualification System', '2026-08-16 03:43:07.45655+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down the 3-5 concrete criteria that make a lead worth pursuing (budget, authority, timeline, need) — one page, not a project.", "Add two qualifying questions to your very first conversation with any new lead, before any pitching happens.", "Track, for two weeks, how much time goes into leads that never had a real chance of closing — use the number to justify the new process to yourself."]', '["all"]', 'INT-269', '156', '[{"name": "MEDDIC", "brief": "Structured qualification framework covering metrics, economic buyer, decision criteria, and pain — ensures only real-fit leads enter the pipeline."}, {"name": "RICE Prioritisation Framework", "brief": "Adapted to score and rank leads by fit and effort required, not just gut feel."}]', '["RC-1183", "RC-1185", "RC-1187"]', '["RC-1187"]', 'Sales Execution', '[3, 4, 5]', '2026-08-16 03:43:07.45655+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('270', 'Sales Psychology', '2026-08-16 03:43:19.801859+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next pipeline review, write down the real hourly cost of chasing an unqualified lead — time spent that a better-fit lead could have used instead.", "The next time you feel pressure to chase a weak lead because the pipeline looks thin, name that feeling out loud before deciding — pressure is not the same as fit.", "Set a rule with yourself: any lead that fails two or more qualifying criteria gets a polite pass, no exceptions during a slow month."]', '["all"]', 'INT-270', '156', '[{"name": "Opportunity Cost Framing", "brief": "Reframe qualification not as turning away revenue, but as protecting limited time for the deals most likely to actually close."}]', '["RC-1184", "RC-1188"]', '["RC-1188"]', 'Sales Execution', '[3, 4, 5]', '2026-08-16 03:43:19.801859+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('271', 'Pipeline Hygiene', '2026-08-16 03:43:19.801859+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Block 15 minutes every week specifically to review your pipeline and mark any lead that no longer deserves the same urgency as a strong-fit one.", "For every new lead, decide within the first conversation whether it goes into a fast-track or a low-priority bucket — do not treat all leads the same by default.", "Remove (not just deprioritise) any lead that has gone quiet for more than three weeks with no real signal — a clean pipeline is more useful than a long one."]', '["all"]', 'INT-271', '156', '[{"name": "Pipeline Triage Ritual", "brief": "A short recurring review that actively removes poor-fit leads rather than letting them linger indefinitely."}]', '["RC-1186", "RC-1189"]', '["RC-1189"]', 'Sales Execution', '[3, 4, 5]', '2026-08-16 03:43:19.801859+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('272', 'Internal Validation, Belief Reframing', '2026-08-16 03:43:43.166925+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Name one decision this month you are proud of that nobody else praised or noticed — write down why it was still the right call.", "Before posting or sharing a win publicly, ask yourself honestly whether it is for the team/customers or for the reaction it will get.", "Identify one person whose opinion you have been chasing more than the evidence deserves, and consciously lower how much weight you give it this month."]', '["all"]', 'INT-272', '96', '[{"name": "Cognitive Restructuring", "brief": "Identify and challenge the belief that external recognition is required to feel legitimate as a founder."}, {"name": "Decision Journal", "brief": "Build a private record of decisions and their reasoning, so validation of judgement comes from evidence, not applause."}]', '["RC-529", "RC-553", "RC-559", "RC-555", "RC-560"]', '["RC-560"]', 'Founder Psychology', '[3, 4, 5, 6, 7]', '2026-08-16 03:43:43.166925+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('273', 'Identity Separation', '2026-08-16 03:43:43.166925+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write one sentence completing: The business has a problem with ___. I am not that problem — practice saying it out loud once this week.", "The next time the business gets criticised, pause before responding and ask: is this actually about me, or about a decision that can be changed?", "List three parts of your identity that exist independently of the business — friendships, skills, interests — and spend deliberate time in at least one this week."]', '["all"]', 'INT-273', '96', '[{"name": "Immunity to Change", "brief": "Surface the hidden belief that the business and the self are the same thing, and the competing commitment that keeps reinforcing it."}]', '["RC-537", "RC-554", "RC-530", "RC-564"]', '["RC-564"]', 'Founder Psychology', '[4, 5, 6, 7]', '2026-08-16 03:43:43.166925+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('274', 'Exposure-Based Confidence Building', '2026-08-16 03:43:43.166925+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Do one thing this week you have been avoiding specifically because of how it might look if it goes badly — start small and deliberately.", "After it happens, write down what you feared would happen versus what actually happened.", "If lack of experience with rejection (e.g. sales, pitching) is part of the fear, treat the first few reps as practice, not a verdict on your ability."]', '["all"]', 'INT-274', '96', '[{"name": "Failure CV Exercise", "brief": "Document past rejections and setbacks alongside what each one actually taught, to normalise rejection as data rather than identity threat."}]', '["RC-538", "RC-561", "RC-532", "RC-539", "RC-534", "RC-533", "RC-535"]', '["RC-533", "RC-535"]', 'Founder Psychology', '[2, 3, 4, 5]', '2026-08-16 03:43:43.166925+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('275', 'Self-Worth Decoupling', '2026-08-16 03:43:43.166925+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Notice one moment this week where you held onto control of a task purely for comfort, not because it genuinely needed you — deliberately let it go instead.", "Ask someone you trust what they actually value about you outside of what you have achieved or built.", "When perfectionism shows up on a task, deliberately ship the good-enough version and observe what, if anything, actually goes wrong."]', '["all"]', 'INT-275', '96', '[{"name": "Immunity to Change", "brief": "Surface the belief that worth must be earned through achievement or control, and the fear underneath perfectionism and the need to be needed."}]', '["RC-531", "RC-556", "RC-562", "RC-557", "RC-558", "RC-536", "RC-540", "RC-563"]', '["RC-540", "RC-563"]', 'Founder Psychology', '[3, 4, 5, 6, 7]', '2026-08-16 03:43:43.166925+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('276', 'Validation Process', '2026-08-16 03:49:30.61104+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Run five customer interviews this week using Mom Test questions — ask about past behaviour, not future intentions.", "In your very next customer conversation, ask directly whether they would pay for this and how much.", "Spend two hours this week reading or talking to someone with real domain experience in this industry, not just your own assumptions."]', '["all"]', 'INT-276', '1', '[{"name": "The Mom Test", "brief": "Structured customer interviews that reveal truth rather than polite encouragement."}, {"name": "Willingness-to-Pay Interview", "brief": "Ask directly about price sensitivity to test real purchase intent, not just interest."}]', '["RC-010", "RC-003", "RC-007"]', '["RC-007"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:30.61104+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('277', 'Bias Interruption', '2026-08-16 03:49:30.61104+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next round of customer conversations, write down what evidence would actually change your mind — then go look for it.", "Deliberately interview two people you expect to say no or push back, not just people likely to agree.", "Separate what customers said they feel (a complaint) from what they actually did (paid, switched, changed behaviour) in your notes from your last five conversations."]', '["all"]', 'INT-277', '1', '[{"name": "Red-Teaming", "brief": "Deliberately assign someone to argue against your market need, forcing disconfirming evidence to surface."}, {"name": "Premortem Analysis", "brief": "Imagine the validation was wrong and work backwards to see what you would have missed."}]', '["RC-004", "RC-001", "RC-006", "RC-005", "RC-009", "RC-002"]', '["RC-009", "RC-002"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:30.61104+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('278', 'Motivation Realignment', '2026-08-16 03:49:30.61104+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write one sentence describing the customer job this solves — if you cannot without mentioning the technology or trend, that is a signal.", "Ask yourself honestly: would you still build this if no investor or trend existed around it? Write down the answer.", "Identify one assumption you are carrying purely because it sounds fundable, and test it against a real customer conversation instead."]', '["all"]', 'INT-278', '1', '[{"name": "Jobs-To-Be-Done (JTBD)", "brief": "Reframe the idea around the customer progress it enables, not the technology or trend behind it."}]', '["RC-012", "RC-011", "RC-008"]', '["RC-008"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:30.61104+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('279', 'Market & Competitive Research', '2026-08-16 03:49:45.704403+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["List every real alternative a customer currently uses instead of your product — including doing nothing.", "Build a rough bottom-up market size estimate: number of realistic customers times what they would pay.", "Write one sentence on what makes your solution meaningfully different, not just present."]', '["all"]', 'INT-279', '2', '[{"name": "Bottom-Up Market Sizing", "brief": "Build TAM from actual customer counts and pricing, not vague industry reports."}, {"name": "Obviously Awesome Positioning Framework", "brief": "Systematically map competitive alternatives to find genuine differentiation."}]', '["RC-015", "RC-013", "RC-021"]', '["RC-021"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:45.704403+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('280', 'Strategic Market View', '2026-08-16 03:49:45.704403+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Talk to three potential customers outside your existing network or social circle this week.", "Write down who exactly makes up the vocal group you have been listening to, and whether they represent the wider market.", "Sketch what this business looks like at 10x its current scale — if you cannot, the strategic thinking gap is real."]', '["all"]', 'INT-280', '2', '[{"name": "CAGE Distance Framework", "brief": "Adapted to check whether your view of the market is shaped by a narrow circle rather than the real customer base."}, {"name": "Three Horizons Framework", "brief": "Force explicit thinking about whether this opportunity can grow beyond its current shape."}]', '["RC-017", "RC-018", "RC-020"]', '["RC-017"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:45.704403+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('281', 'Risk Reframing', '2026-08-16 03:49:45.704403+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Name the version of this idea you would build if you were not worried about it being copied or criticised — compare it to what you are actually building.", "List one visible startup success you have been mentally copying, and identify the specific market conditions that made it work — do those conditions apply to you?", "Separate what you personally enjoy building from what you have actual evidence customers want, in one honest paragraph."]', '["all"]', 'INT-281', '2', '[{"name": "Blue Ocean Strategy", "brief": "Reframe competition and differentiation as a value-cost trade-off rather than something to avoid entirely."}]', '["RC-019", "RC-022", "RC-014", "RC-016"]', '["RC-022", "RC-016"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:49:45.704403+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('282', 'ICP Development', '2026-08-16 03:50:00.201622+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write a one-paragraph description of your single best customer — specific enough that you could name three real people who fit it.", "Run three discovery interviews specifically aimed at understanding who benefits most, not just who shows interest.", "Draft your positioning statement around that one specific customer instead of the general market."]', '["all"]', 'INT-282', '3', '[{"name": "ICP Builder (Ideal Customer Profile)", "brief": "Build a specific customer profile using firmographics, behaviours, and trigger events rather than broad demographics."}]', '["RC-030", "RC-031", "RC-024", "RC-026"]', '["RC-031"]', 'Target Customer & ICP', '[1, 2]', '2026-08-16 03:50:00.201622+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('283', 'Focus Reframing', '2026-08-16 03:50:00.201622+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down what you are afraid will happen if you pick one narrow customer segment — then check whether that fear is realistic.", "Pick the single segment most likely to say yes fastest, and commit to it in writing for the next 90 days.", "Remind yourself: a mass-market vision can still exist later — but only after a beachhead is won, not instead of one."]', '["all"]', 'INT-283', '3', '[{"name": "Beachhead Market Strategy", "brief": "Reframe narrowing to one segment as the fastest path to dominance, not a loss of opportunity."}]', '["RC-028", "RC-025", "RC-023"]', '["RC-025"]', 'Target Customer & ICP', '[1, 2]', '2026-08-16 03:50:00.201622+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('284', 'Commitment & Messaging', '2026-08-16 03:50:00.201622+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Rewrite your current messaging speaking to one specific person, not a general audience — read it back and check if it still sounds generic.", "Commit to naming who your first 100 customers will be before making any decision about scaling beyond them.", "If you keep leaving your options open on who the product serves, write down why — what are you avoiding by not deciding?"]', '["all"]', 'INT-284', '3', '[{"name": "Value Proposition Canvas", "brief": "Force explicit mapping of one customer segment''s jobs, pains, and gains to sharpen messaging."}]', '["RC-029", "RC-027", "RC-032"]', '["RC-032"]', 'Target Customer & ICP', '[1, 2]', '2026-08-16 03:50:00.201622+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('285', 'Commercial Validation', '2026-08-16 03:50:13.567789+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask your next three customer conversations what this problem actually costs them in time or money.", "Write down whether you have ever asked a customer to describe their day-to-day frustration in their own words, unprompted.", "Run one structured discovery interview this week using a written question list, not an open-ended chat."]', '["all"]', 'INT-285', '4', '[{"name": "Willingness-to-Pay Interview", "brief": "Directly test the economic impact of the problem on the customer, not just whether it is annoying."}]', '["RC-036", "RC-035", "RC-034", "RC-042"]', '["RC-042"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:50:13.567789+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('286', 'Motivation Check', '2026-08-16 03:50:13.567789+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask yourself honestly: are you solving this because it is commercially valuable, or because it is intellectually interesting to you?", "Write down what recognition or attention you are hoping this problem earns you — separate that from whether it earns customers.", "Check whether this problem is currently getting outsized attention in the media or investor conversations, and whether that is driving your interest more than customer evidence."]', '["all"]', 'INT-286', '4', '[{"name": "Jobs-To-Be-Done (JTBD)", "brief": "Reframe problem selection around customer progress rather than technical interest or personal recognition."}]', '["RC-039", "RC-033", "RC-041", "RC-040"]', '["RC-040"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:50:13.567789+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('287', 'Urgency Testing', '2026-08-16 03:50:13.567789+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask your next five prospective customers directly: how urgently do you need this solved, on a scale of 1 to 10?", "Check how many people outside your own immediate circle report experiencing this problem — do not rely on your own frustration as the sample."]', '["all"]', 'INT-287', '4', '[{"name": "Van Westendorp Price Sensitivity Meter", "brief": "Adapted to test urgency by asking directly how soon and how badly customers need a solution."}]', '["RC-038", "RC-037"]', '["RC-037"]', 'Idea & Validation', '[1, 2]', '2026-08-16 03:50:13.567789+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('288', 'Identity Separation', '2026-08-16 03:50:29.703135+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write one sentence completing: This idea has a problem with ___. I am not that problem.", "List three things about you as a founder that would still be true even if this specific idea failed.", "Ask yourself honestly what evidence would need to exist for you to admit the current path is not working — write it down before you need it."]', '["all"]', 'INT-288', '5', '[{"name": "Immunity to Change", "brief": "Surface the belief that changing direction means personal failure, and the competing commitment keeping the founder stuck."}]', '["RC-043", "RC-044", "RC-050"]', '["RC-050"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 03:50:29.703135+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('289', 'Stakeholder Communication', '2026-08-16 03:50:29.703135+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Draft how you would explain a potential change of direction to your investors or team — most founders find it sounds more reasonable written down than it feels in their head.", "Ask one team member directly how they would feel about a change in direction, rather than assuming resistance.", "Separate what you have told people about the idea from what you have actually promised — often it is less binding than it feels."]', '["all"]', 'INT-289', '5', '[{"name": "Monthly Investor Update Framework", "brief": "Build a habit of honest, regular updates so a pivot is a natural continuation of the story, not a shocking reversal."}]', '["RC-046", "RC-048", "RC-047"]', '["RC-047"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 03:50:29.703135+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('290', 'Decision Clarity Under Strain', '2026-08-16 03:50:29.703135+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["List the time and money already spent on the current path — then set it aside and ask only what happens next, evaluated fresh.", "If you are exhausted, protect one real day of rest before making any big direction decision — burnout distorts judgement.", "Write down what specifically feels uncertain about changing direction, then identify which of those unknowns you could actually test cheaply."]', '["all"]', 'INT-290', '5', '[{"name": "Premortem Analysis", "brief": "Imagine the current path has already failed and work backwards to see the signal clearly, bypassing sunk-cost reasoning."}, {"name": "Two-Way Door Framework", "brief": "Reframe a pivot as a reversible decision rather than a final, high-stakes one."}]', '["RC-051", "RC-052", "RC-045", "RC-049"]', '["RC-049"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 03:50:29.703135+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('291', 'Feedback Systems', '2026-08-16 04:25:36.680982+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Block one recurring hour each week specifically for customer conversations — treat it as non-negotiable as a board meeting.", "Set up one simple shared doc or spreadsheet to log every piece of customer feedback the moment you hear it.", "Review last month''s calendar — count how many hours went to product work versus customer conversations, and notice the ratio."]', '["all"]', 'INT-291', '6', '[{"name": "Continuous Discovery Habits", "brief": "Build weekly customer conversations into the regular rhythm of the business, not a one-time exercise."}]', '["RC-057", "RC-058", "RC-061"]', '["RC-061"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 04:25:36.680982+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('292', 'Feedback Exposure', '2026-08-16 04:25:36.680982+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next customer call, write down what you are afraid you might hear — then go have the conversation anyway.", "After a piece of critical feedback, separate what was said about the product from anything you are telling yourself about your worth as a founder.", "Schedule one customer conversation this week even if part of you wants to avoid it — momentum reduces the dread faster than waiting does."]', '["all"]', 'INT-292', '6', '[{"name": "Cognitive Restructuring", "brief": "Challenge the belief that customer criticism is a personal verdict rather than useful data."}]', '["RC-055", "RC-062", "RC-054"]', '["RC-055"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 04:25:36.680982+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('293', 'Listening Skill-Building', '2026-08-16 04:25:36.680982+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next customer conversation, ask one open question and then stay silent for at least ten seconds before speaking again.", "Write down one assumption you currently hold about what customers want — then go test it directly instead of building around it.", "Ship something imperfect to real customers this week instead of waiting for it to feel ready."]', '["all"]', 'INT-293', '6', '[{"name": "The Mom Test", "brief": "Structured listening technique that surfaces what customers actually think rather than what the founder assumes."}]', '["RC-053", "RC-056", "RC-059", "RC-060"]', '["RC-060"]', 'Idea & Validation', '[2, 3, 4]', '2026-08-16 04:25:36.680982+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('294', 'Validation Education', '2026-08-16 04:25:51.755735+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Read or watch one solid explainer on Lean Startup validation before writing any more code this week.", "Write down which validation steps you have been skipping and why — be honest about whether it was a real decision or just avoidance."]', '["all"]', 'INT-294', '7', '[{"name": "Build-Measure-Learn Loop", "brief": "Learn the actual sequence — validated learning before building — rather than treating validation as an optional extra step."}]', '["RC-066", "RC-070"]', '["RC-070"]', 'Idea & Validation', '[1, 2]', '2026-08-16 04:25:51.755735+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('295', 'Tolerating Ambiguity', '2026-08-16 04:25:51.755735+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Notice the next time you feel the urge to start building to escape uncertainty — sit with that discomfort for one day before acting on it.", "Write down the single biggest unknown about the problem right now, and spend this week reducing that unknown instead of building.", "Give yourself explicit permission to spend a week ''not producing code'' — track what you learn instead of what you shipped."]', '["all"]', 'INT-295', '7', '[{"name": "Premortem Analysis", "brief": "Use structured reflection to sit with uncertainty productively instead of resolving discomfort by building prematurely."}]', '["RC-065", "RC-068", "RC-067"]', '["RC-067"]', 'Idea & Validation', '[1, 2]', '2026-08-16 04:25:51.755735+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('296', 'Redirecting Builder Energy', '2026-08-16 04:25:51.755735+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Treat your next round of customer interviews as a real ''build'' — track it with the same seriousness as a sprint.", "Before your next coding session, write one sentence on what customer evidence justifies building this specific thing right now.", "Notice if you are building partly to have something to show people — ask whether a validated insight would satisfy that need just as well."]', '["all"]', 'INT-296', '7', '[{"name": "Opportunity Solution Tree", "brief": "Redirect the energy of building toward mapping the full opportunity space before committing to one solution."}]', '["RC-069", "RC-064", "RC-063", "RC-072", "RC-071"]', '["RC-071"]', 'Idea & Validation', '[1, 2]', '2026-08-16 04:25:51.755735+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('297', 'GTM System Building', '2026-08-16 04:26:06.950941+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Draft a one-page GTM canvas covering ICP, value proposition, pricing, channels, and sales motion — not just marketing tactics.", "Map your current customer journey from first touch to purchase — mark where the path is undefined or assumed.", "Read one solid explainer distinguishing GTM strategy from marketing before planning your next campaign."]', '["all"]', 'INT-297', '8', '[{"name": "Go-to-Market Strategy Canvas", "brief": "Build the full commercial architecture — ICP, pricing, channels, sales motion — not just a marketing plan."}, {"name": "Customer Journey Mapping", "brief": "Map every step from first awareness through purchase and retention to find where the real system is missing."}]', '["RC-081", "RC-074", "RC-079", "RC-076"]', '["RC-076"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:06.950941+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('298', 'Revenue-Linked Metrics', '2026-08-16 04:26:06.950941+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["List the metrics you currently track — for each one, ask whether it actually connects to revenue or just to visibility.", "Add one revenue-linked metric (conversion rate, paying customers, revenue per channel) to whatever you review weekly."]', '["all"]', 'INT-298', '8', '[{"name": "AARRR Funnel (Pirate Metrics)", "brief": "Track the full funnel from acquisition to revenue, not just top-of-funnel reach and awareness."}]', '["RC-077", "RC-075"]', '["RC-075"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:06.950941+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('299', 'Tactic Discipline', '2026-08-16 04:26:06.950941+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next marketing activity, ask what business outcome it is actually meant to produce — write it down in advance.", "List every channel you are currently active on and honestly assess which ones are producing real results versus just activity.", "The next time you consider copying a tactic you saw online, ask what underlying business mechanics made it work for them — and whether those apply to you."]', '["all"]', 'INT-299', '8', '[{"name": "Bullseye Framework", "brief": "Test channels systematically instead of copying what looks exciting or what one influencer or competitor is doing."}]', '["RC-073", "RC-080", "RC-082", "RC-078"]', '["RC-078"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:06.950941+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('300', 'ICP Research & Definition', '2026-08-16 04:26:19.587352+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Run five structured discovery interviews this week aimed specifically at finding your best-fit customer pattern, not just any willing talker.", "Set up a simple spreadsheet or CRM to log basic data on every lead — without it, targeting stays a guess forever.", "Write one paragraph naming who your product serves best and why, based on evidence from actual customers, not assumption."]', '["all"]', 'INT-300', '9', '[{"name": "ICP Builder (Ideal Customer Profile)", "brief": "Build a specific, evidence-based customer profile using firmographics, behaviours, and pain severity."}, {"name": "Obviously Awesome Positioning Framework", "brief": "Map competitive alternatives to sharpen positioning once the ICP is clear."}]', '["RC-086", "RC-093", "RC-090", "RC-094", "RC-084", "RC-088", "RC-087"]', '["RC-087"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:19.587352+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('301', 'Focus Reframing', '2026-08-16 04:26:19.587352+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down what you are afraid will happen if you say no to customers outside your ideal segment — check whether that fear matches reality.", "Pick the single segment showing the strongest current signal and commit to it in writing for the next quarter.", "The next time cash pressure tempts you to chase a poor-fit lead, name that pressure explicitly before deciding whether to pursue it."]', '["all"]', 'INT-301', '9', '[{"name": "Beachhead Market Strategy", "brief": "Reframe narrowing to one segment as the fastest path to real traction, not a loss of potential customers."}]', '["RC-091", "RC-085", "RC-092", "RC-083", "RC-089"]', '["RC-089"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:19.587352+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('302', 'Channel Testing Infrastructure', '2026-08-16 04:26:33.417578+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up basic tracking (even a simple UTM + spreadsheet) so you know which channel any given customer actually came from.", "Pick one channel and commit to running it for a fixed minimum period (e.g. 6 weeks) before judging results — write the commitment down now.", "Review last month''s channel spend or effort and identify where you have no real data on what worked."]', '["all"]', 'INT-302', '10', '[{"name": "Bullseye Framework", "brief": "Systematically test all viable channels through outer, middle, and inner circles rather than guessing."}]', '["RC-098", "RC-106", "RC-102", "RC-104"]', '["RC-104"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:33.417578+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('303', 'Evidence-Based Channel Selection', '2026-08-16 04:26:33.417578+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before committing further resource to your current main channel, write down what actual evidence supports it versus what was assumed.", "List two other channels you have not yet tested and run one small, cheap experiment in each this month.", "If one early win drove your current channel choice, check whether the conditions that produced it are still true today."]', '["all"]', 'INT-303', '10', '[{"name": "Bullseye Framework", "brief": "Test the outer ring of possible channels with small experiments before committing significant resources to any one."}]', '["RC-095", "RC-103", "RC-100", "RC-099"]', '["RC-099"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:33.417578+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('304', 'Customer-Led Channel Choice', '2026-08-16 04:26:33.417578+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask three current or prospective customers directly where they spend time online or how they typically find solutions like yours.", "Notice if your current channel choice reflects where you personally enjoy spending time rather than where customers are.", "The next time a new platform or trend tempts you, finish testing your current channel properly before switching."]', '["all"]', 'INT-304', '10', '[{"name": "ICP Builder (Ideal Customer Profile)", "brief": "Ground channel selection in where the ideal customer actually spends time, not personal preference or excitement."}]', '["RC-105", "RC-096", "RC-097", "RC-101"]', '["RC-101"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:26:33.417578+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('305', 'Customer Language Research', '2026-08-16 04:32:28.896127+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next five customer conversations, write down the exact phrases they use to describe the problem — do not paraphrase.", "Rewrite one piece of current messaging using only words pulled directly from real customer conversations.", "Test your current tagline or headline on three people outside the company and ask what they think it means."]', '["all"]', 'INT-305', '11', '[{"name": "The Mom Test", "brief": "Capture the exact words customers use to describe their problem, not the founder''s own vocabulary."}]', '["RC-115", "RC-107", "RC-113", "RC-118"]', '["RC-118"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:28.896127+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('306', 'Positioning Definition', '2026-08-16 04:32:28.896127+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write one sentence explaining why a customer would choose you over the next best alternative — including doing nothing.", "Pick the single customer segment your messaging should speak to first, and set aside messaging for the others for now.", "List your top three competitors and write down specifically what you do differently, not just better."]', '["all"]', 'INT-306', '11', '[{"name": "Obviously Awesome Positioning Framework", "brief": "Systematically define competitive alternatives, unique attributes, and target customer to sharpen positioning."}]', '["RC-110", "RC-112", "RC-114"]', '["RC-114"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:28.896127+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('307', 'Messaging Specificity', '2026-08-16 04:32:28.896127+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Rewrite your homepage headline to make one specific, concrete claim instead of a general benefit statement.", "Read your current messaging out loud to someone unfamiliar with the product — flag every piece of jargon they don''t understand.", "Notice the next time you soften a claim out of fear of being held to it — write the specific version instead and see what actually happens."]', '["all"]', 'INT-307', '11', '[{"name": "Jobs-To-Be-Done (JTBD)", "brief": "Rewrite messaging around the specific outcome customers hire the product for, not features or founder assumptions."}]', '["RC-117", "RC-111", "RC-109", "RC-116", "RC-108"]', '["RC-108"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:28.896127+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('308', 'Pricing Research', '2026-08-16 04:32:43.839749+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask your next five prospects directly what they would expect to pay for this, before you tell them your price.", "Calculate your current gross margin at today''s price — many founders have never actually run this number.", "Test one small pricing change (a new tier, a different number) with a subset of prospects this month."]', '["all"]', 'INT-308', '12', '[{"name": "Van Westendorp Price Sensitivity Meter", "brief": "Test acceptable price ranges directly with customers instead of guessing."}, {"name": "Value-Based Pricing Framework", "brief": "Set prices based on the economic value delivered, not cost or competitor prices."}]', '["RC-129", "RC-120", "RC-127", "RC-125"]', '["RC-125"]', 'Go-To-Market', '[2, 3, 4, 5]', '2026-08-16 04:32:43.839749+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('309', 'Pricing Confidence', '2026-08-16 04:32:43.839749+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next pricing conversation, write down what you are afraid will happen if you state your price plainly.", "Ask a trusted peer or mentor to review your pricing and tell you honestly whether it undervalues what you deliver.", "Practice saying your price out loud once before the next sales call — notice if it feels harder to say than it should."]', '["all"]', 'INT-309', '12', '[{"name": "Cognitive Restructuring", "brief": "Challenge the belief that charging fairly for value is an imposition rather than a normal business practice."}]', '["RC-124", "RC-119", "RC-121"]', '["RC-121"]', 'Go-To-Market', '[2, 3, 4, 5]', '2026-08-16 04:32:43.839749+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('310', 'Evidence-Based Pricing Decisions', '2026-08-16 04:32:43.839749+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down where your current price actually came from — a competitor, a gut feeling, or a customer conversation — and be honest about which.", "The next time a customer pushes back on price, resist the urge to immediately discount — ask what specifically feels expensive first.", "Compare your pricing against the actual value delivered (time saved, revenue generated) rather than against a competitor''s number."]', '["all"]', 'INT-310', '12', '[{"name": "Value-Based Pricing Framework", "brief": "Anchor pricing decisions to customer value and evidence, not competitor prices, emotion, or the desire to please."}]', '["RC-128", "RC-130", "RC-122", "RC-126", "RC-123"]', '["RC-123"]', 'Go-To-Market', '[2, 3, 4, 5]', '2026-08-16 04:32:43.839749+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('311', 'Sales Process Building', '2026-08-16 04:32:58.116009+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up a simple tracker (even a spreadsheet) to log every prospect conversation and its status — no more relying on memory.", "Map out the buying journey your last three customers actually went through, step by step.", "Write down where you have been expecting marketing to do the job that only direct sales conversations can do."]', '["all"]', 'INT-311', '13', '[{"name": "Customer Journey Mapping", "brief": "Map the actual stages a buyer goes through before purchasing, rather than assuming marketing alone will convert them."}]', '["RC-139", "RC-136", "RC-140", "RC-137"]', '["RC-137"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:58.116009+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('312', 'Sales Skill Building', '2026-08-16 04:32:58.116009+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Review your last three lost deals and write down the actual reason each one said no — not your guess, the real reason if you can find out.", "Read or watch one solid resource on objection handling before your next sales call.", "In your next customer conversation, ask three discovery questions before mentioning your product at all."]', '["all"]', 'INT-312', '13', '[{"name": "SPIN Selling", "brief": "Learn structured discovery questioning instead of pitching before understanding the customer''s situation."}]', '["RC-141", "RC-138", "RC-132", "RC-135"]', '["RC-135"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:58.116009+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('313', 'Sales Avoidance Reframing', '2026-08-16 04:32:58.116009+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Reach out to one prospect today specifically to practice tolerating the discomfort of asking for a commitment.", "Write down what you believe will happen if you get rejected on a sales call — then check that belief against what actually happens.", "Track how many hours went to engineering versus sales conversations this week, and notice the gap honestly."]', '["all"]', 'INT-313', '13', '[{"name": "Cognitive Restructuring", "brief": "Reframe selling as serving a real need rather than an imposition, to reduce avoidance of sales activity."}]', '["RC-142", "RC-134", "RC-131", "RC-133"]', '["RC-133"]', 'Go-To-Market', '[2, 3, 4]', '2026-08-16 04:32:58.116009+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('314', 'Retention Measurement & Systems', '2026-08-16 04:33:13.642657+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Calculate your current churn rate this week, even roughly — if you cannot, that gap is the first thing to fix.", "Set up one simple check-in touchpoint with existing customers to catch dissatisfaction before it becomes churn.", "Ask your three most satisfied customers if they would refer someone — and make asking a repeatable habit, not a one-off."]', '["all"]', 'INT-314', '14', '[{"name": "Customer Success Framework", "brief": "Build a proactive system for ensuring customers achieve their desired outcome, not just reactive support."}, {"name": "Net Revenue Retention (NRR)", "brief": "Track the metric that actually reveals whether existing customers are growing or quietly leaving."}]', '["RC-152", "RC-149", "RC-143", "RC-151", "RC-147", "RC-145"]', '["RC-145"]', 'Go-To-Market', '[3, 4, 5, 6]', '2026-08-16 04:33:13.642657+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('315', 'Growth Mindset Reframing', '2026-08-16 04:33:13.642657+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next investor update, include a retention or NRR figure alongside acquisition numbers — normalize reporting on both.", "Notice the emotional high of signing a new customer versus the quieter satisfaction of a renewal — name that bias explicitly.", "Set one retention-related goal for this month with the same seriousness as your acquisition goal."]', '["all"]', 'INT-315', '14', '[{"name": "Net Revenue Retention (NRR)", "brief": "Reframe retention as a growth lever investors care about too, not a defensive afterthought."}]', '["RC-154", "RC-144", "RC-146"]', '["RC-146"]', 'Go-To-Market', '[3, 4, 5, 6]', '2026-08-16 04:33:13.642657+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('316', 'Churn Cost Awareness', '2026-08-16 04:33:13.642657+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Calculate roughly how much revenue you lost to churn last quarter, and compare it to what you spent on acquisition.", "List the top three complaints customers raise most often, and fix the highest-frequency one first.", "Before your next growth decision, ask whether it trades short-term acquisition for long-term retention — and whether that trade is worth it."]', '["all"]', 'INT-316', '14', '[{"name": "SaaS Unit Economics Framework", "brief": "Calculate customer lifetime value to make the true cost of churn visible and comparable to acquisition spend."}]', '["RC-150", "RC-148", "RC-153"]', '["RC-153"]', 'Go-To-Market', '[3, 4, 5, 6]', '2026-08-16 04:33:13.642657+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('317', 'Outbound System Building', '2026-08-16 04:33:28.104762+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up a simple weekly prospecting habit — a fixed number of new outreach attempts every week, regardless of how revenue looks.", "Document your current outreach process, even roughly, so it does not live only in your head.", "Track basic pipeline numbers (leads contacted, replies, meetings booked) weekly, even in a simple spreadsheet."]', '["all"]', 'INT-317', '15', '[{"name": "Outbound Cadence Design", "brief": "Build a structured multi-touch outreach sequence instead of one-off, inconsistent attempts."}]', '["RC-160", "RC-155", "RC-159", "RC-167"]', '["RC-167"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:33:28.104762+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('318', 'Credibility & Positioning', '2026-08-16 04:33:28.104762+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Collect one testimonial or short case study from your best current customer this week.", "Rewrite your one-line value proposition and test it on three people unfamiliar with the business.", "Ask your happiest customer for one direct introduction to someone else who might need this."]', '["all"]', 'INT-318', '15', '[{"name": "Obviously Awesome Positioning Framework", "brief": "Sharpen the value proposition so prospects immediately understand why they should care."}]', '["RC-165", "RC-163", "RC-158", "RC-164", "RC-161", "RC-166"]', '["RC-166"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:33:28.104762+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('319', 'Consistency & Focus', '2026-08-16 04:33:28.104762+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write a one-paragraph description of your ideal customer and only prospect against that profile for the next two weeks.", "Notice if outreach only happens when revenue feels urgent — build a fixed weekly cadence instead of reactive bursts.", "If you are running on empty, protect one real recovery day this week — burnout is quietly draining your outreach consistency too."]', '["all"]', 'INT-319', '15', '[{"name": "ICP Builder (Ideal Customer Profile)", "brief": "Define exactly who to reach out to, so prospecting effort stops being random and scattered."}]', '["RC-156", "RC-168", "RC-162", "RC-157"]', '["RC-157"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:33:28.104762+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('320', 'Sales Execution Habits', '2026-08-16 04:36:51.584753+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up a simple follow-up tracker so no interested prospect falls through the cracks again.", "Review your last five stalled deals and check whether they were actually qualified before you invested time in them.", "In your next call, count how much you talk versus listen — aim to listen more than you speak."]', '["all"]', 'INT-320', '16', '[{"name": "MEDDIC", "brief": "Qualify deals properly and track follow-up systematically instead of letting interested prospects go cold."}]', '["RC-180", "RC-175", "RC-171", "RC-170"]', '["RC-170"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:36:51.584753+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('321', 'Sales Skill Development', '2026-08-16 04:36:51.584753+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next sales call, prepare three discovery questions and ask them before mentioning your product.", "Write down the top three objections you hear most often and draft a confident response to each in advance.", "Practice telling the story of what changes for the customer after they buy — rehearse it out loud once."]', '["all"]', 'INT-321', '16', '[{"name": "SPIN Selling", "brief": "Structured discovery questioning to understand the customer''s real situation before pitching."}, {"name": "Challenger Sale Framework", "brief": "Teach the customer something new and take control of the conversation rather than passively presenting."}]', '["RC-174", "RC-179", "RC-169", "RC-173", "RC-176", "RC-182"]', '["RC-182"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:36:51.584753+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('322', 'Closing Confidence', '2026-08-16 04:36:51.584753+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next call, practice directly asking for the next step instead of letting the conversation trail off.", "State your price plainly once this week without qualifying or apologizing for it.", "Before a negotiation, write down your walk-away point in advance so you are not deciding under pressure."]', '["all"]', 'INT-322', '16', '[{"name": "Cognitive Restructuring", "brief": "Challenge the belief that asking for commitment is aggressive or that discussing price signals weakness."}]', '["RC-172", "RC-177", "RC-181", "RC-178"]', '["RC-178"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:36:51.584753+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('323', 'Unit Economics Foundation', '2026-08-16 04:37:05.205777+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Calculate your current CAC and LTV this week, even roughly — most founders have never actually run these numbers.", "Build a simple financial model projecting revenue against real costs, not assumed ones.", "Run one small pricing experiment (a new tier or price point) with a subset of prospects this month."]', '["all"]', 'INT-323', '17', '[{"name": "SaaS Unit Economics Framework", "brief": "Calculate CAC, LTV, and gross margin as the baseline numbers every pricing decision should be checked against."}]', '["RC-195", "RC-192", "RC-191", "RC-183", "RC-189", "RC-187", "RC-186"]', '["RC-186"]', 'Sales & Revenue', '[3, 4, 5]', '2026-08-16 04:37:05.205777+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('324', 'Evidence-Based Pricing Decisions', '2026-08-16 04:37:05.205777+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down where your current price actually came from — a competitor, a gut feeling, or real customer data.", "Check whether your assumption that customers will pay anything for this product has ever actually been tested."]', '["all"]', 'INT-324', '17', '[{"name": "Value-Based Pricing Framework", "brief": "Anchor pricing to customer value and evidence rather than competitor prices or founder feeling."}]', '["RC-190", "RC-185", "RC-193"]', '["RC-193"]', 'Sales & Revenue', '[3, 4, 5]', '2026-08-16 04:37:05.205777+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('325', 'Pricing Discipline', '2026-08-16 04:37:05.205777+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next discount, check your actual gross margin at that discounted price — many discounts turn a profitable deal unprofitable.", "Track revenue and profit separately this month — notice if you have been treating them as the same thing.", "The next time revenue pressure tempts a discount, name that pressure explicitly before deciding."]', '["all"]', 'INT-325', '17', '[{"name": "Cognitive Restructuring", "brief": "Separate short-term cash pressure and discomfort with charging from what the business actually needs to sustain itself."}]', '["RC-184", "RC-188", "RC-196", "RC-194"]', '["RC-194"]', 'Sales & Revenue', '[3, 4, 5]', '2026-08-16 04:37:05.205777+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('326', 'Revenue Model Design', '2026-08-16 04:37:19.487996+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Assign one person (even yourself, explicitly) as the owner of revenue model decisions.", "Research how customers in your market currently spend money on solving this type of problem.", "Draft one page mapping your revenue model — pricing tiers, expansion paths — even if it is rough."]', '["all"]', 'INT-326', '18', '[{"name": "Business Model Design", "brief": "Deliberately design revenue mechanisms and ownership rather than leaving them undefined."}, {"name": "Willingness-to-Pay Interview", "brief": "Test revenue model assumptions directly with customers early, not after building at scale."}]', '["RC-201", "RC-200", "RC-210", "RC-209", "RC-204", "RC-207", "RC-203"]', '["RC-203"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:37:19.487996+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('327', 'Growth-vs-Revenue Reframing', '2026-08-16 04:37:19.487996+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down what specifically you are assuming will happen once you have enough users — check whether that assumption has ever been tested.", "In your next investor update, include one revenue-readiness metric alongside growth metrics."]', '["all"]', 'INT-327', '18', '[{"name": "Bowtie Model", "brief": "Reframe revenue and retention as part of growth itself, not something to defer until after acquisition."}]', '["RC-197", "RC-199", "RC-206"]', '["RC-206"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:37:19.487996+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('328', 'Monetization Discipline', '2026-08-16 04:37:19.487996+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Ask one prospective customer directly what they would pay for this, even if the conversation feels uncomfortable.", "Notice how much of your recent time went to product work versus revenue design — write down the honest ratio.", "Test charging a small amount for something currently free, and see what actually happens to adoption."]', '["all"]', 'INT-328', '18', '[{"name": "Willingness-to-Pay Interview", "brief": "Practice the direct pricing conversation instead of avoiding it."}]', '["RC-208", "RC-198", "RC-202", "RC-205"]', '["RC-205"]', 'Sales & Revenue', '[2, 3, 4]', '2026-08-16 04:37:19.487996+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('329', 'Retention Measurement & Ownership', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Assign one person as explicitly responsible for reducing churn — nobody owns it today.", "Calculate your current churn rate this week, even roughly.", "Set up one recurring check-in touchpoint with existing customers to catch dissatisfaction early."]', '["all"]', 'INT-329', '19', '[{"name": "Customer Success Framework", "brief": "Build a proactive system with clear ownership for ensuring customers reach their desired outcome."}]', '["RC-427", "RC-219", "RC-214", "RC-428", "RC-430", "RC-224", "RC-432", "RC-218"]', '["RC-432"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:39:23.279575+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('330', 'Product Value Delivery', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Interview three churned customers about what stopped delivering value for them, in their own words.", "List your top three recurring support issues and fix the most frequent one first.", "Check whether customers are actually experiencing the value you believe the product delivers, or whether that value is unclear to them."]', '["all"]', 'INT-330', '19', '[{"name": "Product-Market Fit Pyramid", "brief": "Diagnose which layer — value delivery, communication, or reliability — is actually breaking retention."}]', '["RC-423", "RC-424", "RC-217", "RC-421", "RC-212", "RC-426"]', '["RC-426"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:37:40.456071+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('331', 'Expectation & Fit Alignment', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Compare what your sales conversations promise against what the product actually delivers — flag any gaps.", "Check whether recent churned customers were ever a strong ICP fit to begin with."]', '["all"]', 'INT-331', '19', '[{"name": "ICP Builder (Ideal Customer Profile)", "brief": "Ensure sales promises and acquired customers actually match what the product delivers and who it serves best."}]', '["RC-429", "RC-425", "RC-221", "RC-216"]', '["RC-216"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:37:40.456071+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('332', 'Proactive Revenue Management', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up one leading indicator (usage drop, support tickets) that flags at-risk customers before they churn.", "Review whether your pricing still matches the perceived value for your longest-tenured customers."]', '["all"]', 'INT-332', '19', '[{"name": "Net Revenue Retention (NRR)", "brief": "Track retention proactively so pricing and revenue problems surface before customers decide to leave."}]', '["RC-223", "RC-431", "RC-220"]', '["RC-220"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:37:40.456071+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('333', 'Discounting Psychology', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next discount, name the discomfort driving it — losing the deal — and check whether discounting actually solves that.", "Review your last five discounted deals: did the discount solve a real objection, or was it a shortcut around discomfort?"]', '["all"]', 'INT-333', '19', '[{"name": "Cognitive Restructuring", "brief": "Address the discomfort of losing a deal that drives reflexive discounting, separate from the actual value question."}]', '["RC-213", "RC-211", "RC-222"]', '["RC-222"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:37:40.456071+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('334', 'Onboarding Design', '2026-08-16 04:37:40.456071+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Map your current onboarding step by step and identify where customers are most likely to drop off before experiencing real value.", "Reduce the time to first meaningful value in onboarding by removing one unnecessary step."]', '["all"]', 'INT-334', '19', '[{"name": "Product-Market Fit Pyramid", "brief": "Design onboarding to get customers to their first moment of real value as fast as possible."}]', '["RC-215", "RC-422"]', '["RC-422"]', 'Sales & Revenue', '[3, 4, 5, 6]', '2026-08-16 04:37:40.456071+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('335', 'Co-founder Structure', '2026-08-16 04:37:53.7526+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down, together, who has final say on each major decision category — do not assume it is already clear.", "Have an explicit conversation about where each of you wants the company to be in three years — do not assume alignment."]', '["all"]', 'INT-335', '20', '[{"name": "RACI Matrix", "brief": "Explicitly define who decides what, closing the ambiguity that fuels conflict."}]', '["RC-269", "RC-272", "RC-261"]', '["RC-261"]', 'Team & Leadership', '[2, 3, 4]', '2026-08-16 04:37:53.7526+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('336', 'Co-founder Trust Repair', '2026-08-16 04:37:53.7526+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Name one small grievance you have been holding onto and raise it directly this week, before it compounds further.", "During your next disagreement, notice if the tension is really about the decision or about unspoken credit and recognition."]', '["all"]', 'INT-336', '20', '[{"name": "Five Dysfunctions of a Team", "brief": "Rebuild trust and address unspoken conflict directly rather than letting small grievances compound."}]', '["RC-270", "RC-265", "RC-268", "RC-271"]', '["RC-271"]', 'Team & Leadership', '[2, 3, 4]', '2026-08-16 04:37:53.7526+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('337', 'Co-founder Practical Alignment', '2026-08-16 04:37:53.7526+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down each co-founder''s actual role and responsibilities — check for overlap or gaps causing friction.", "Have the difficult equity or contribution conversation you have been postponing — delay only makes it harder."]', '["all"]', 'INT-337', '20', '[{"name": "RACI Matrix", "brief": "Clarify roles and contribution expectations to remove the ambiguity behind resentment."}]', '["RC-267", "RC-263", "RC-264", "RC-266", "RC-262"]', '["RC-262"]', 'Team & Leadership', '[2, 3, 4]', '2026-08-16 04:37:53.7526+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('338', 'Delegation Infrastructure', '2026-08-16 04:38:06.980815+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up one simple metric per key role so you can check progress without checking in constantly.", "Document one process this week that currently only exists in your head."]', '["all"]', 'INT-338', '21', '[{"name": "EOS — Entrepreneurial Operating System", "brief": "Build the scorecards and systems that make delegation trustworthy instead of relying on direct observation."}]', '["RC-282", "RC-280", "RC-277"]', '["RC-277"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:06.980815+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('339', 'Control Psychology', '2026-08-16 04:38:06.980815+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Pick one task this week that you would normally check in on constantly, and deliberately let it go without checking.", "Notice what specifically feels unsafe about not being involved — write it down before deciding whether it is actually true."]', '["all"]', 'INT-339', '21', '[{"name": "Delegation Ladder (7 Levels)", "brief": "Match delegation level to the discomfort involved, building tolerance for releasing control gradually."}]', '["RC-276", "RC-278", "RC-273", "RC-274", "RC-281", "RC-283"]', '["RC-283"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:06.980815+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('340', 'Trust Rebuilding', '2026-08-16 04:38:06.980815+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Identify one team member who has earned more autonomy than they currently have, and give it to them explicitly.", "Separate a specific past mistake from a general belief that delegation does not work — check if the evidence really supports the general belief."]', '["all"]', 'INT-340', '21', '[{"name": "Situational Leadership II", "brief": "Match trust and autonomy to each person''s actual demonstrated competence rather than past mistakes generally."}]', '["RC-279", "RC-284", "RC-275"]', '["RC-275"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:06.980815+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('341', 'Founder Support Access', '2026-08-16 04:38:18.249344+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Complete a founder capability audit identifying your three largest skill gaps.", "Reach out to three experienced founders or mentors for regular monthly accountability.", "Decide whether your biggest gap is best solved through a co-founder, advisor, or first senior hire."]', '["all"]', 'INT-341', '22', '[{"name": "Founder Capability Audit", "brief": "Assess strengths and gaps to determine whether a co-founder, advisor, or first hire is the highest-leverage fix."}]', '["RC-811", "RC-813", "RC-812", "RC-808"]', '["RC-808"]', 'Team & Leadership', '[3, 4, 5, 6]', '2026-08-16 04:38:18.249344+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('342', 'Partnership Psychology', '2026-08-16 04:38:18.249344+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down specifically what a previous co-founder experience (or the fear of one) taught you — check whether it applies to every possible partnership or just that one.", "Name one thing you would need to see in someone before trusting them with real ownership of the vision.", "Notice the emotional weight you are carrying alone this week, and identify one person you could share even part of it with."]', '["all"]', 'INT-342', '22', '[{"name": "Cognitive Restructuring", "brief": "Address the underlying trust and past-fallout barriers that keep the founder from ever seriously considering a co-founder."}]', '["RC-809", "RC-810", "RC-814", "RC-815"]', '["RC-815"]', 'Team & Leadership', '[3, 4, 5, 6]', '2026-08-16 04:38:18.249344+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('343', 'Hiring Process', '2026-08-16 04:38:30.541255+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write a one-page scorecard defining what success looks like in the role before you post the job.", "Design three structured interview questions that actually test the specific skill the role needs.", "Build a basic onboarding checklist so a well-chosen hire does not fail from a weak start."]', '["all"]', 'INT-343', '23', '[{"name": "WHO Hiring Method", "brief": "Use scorecards and structured interviews instead of subjective, inconsistent evaluation."}]', '["RC-237", "RC-238", "RC-247", "RC-241", "RC-242", "RC-246"]', '["RC-246"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:30.541255+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('344', 'Bias Interruption', '2026-08-16 04:38:30.541255+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before your next final hiring decision, write down the evidence-based reason separate from how much you liked the candidate personally.", "Notice if you are drawn to a candidate because they remind you of yourself — check that against the actual scorecard."]', '["all"]', 'INT-344', '23', '[{"name": "WHO Hiring Method", "brief": "Structured evaluation reduces the influence of charisma, similarity, and personal chemistry on hiring decisions."}]', '["RC-245", "RC-240", "RC-239", "RC-248"]', '["RC-248"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:30.541255+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('345', 'Candidate Verification', '2026-08-16 04:38:30.541255+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Run a real reference check on your next candidate — ask specific questions about how they actually work, not just whether they were good.", "Explicitly assess culture and working-style fit as part of the decision, not just technical skill."]', '["all"]', 'INT-345', '23', '[{"name": "WHO Hiring Method", "brief": "Deep reference checks verify past performance and cultural fit rather than relying on the interview alone."}]', '["RC-244", "RC-243"]', '["RC-243"]', 'Team & Leadership', '[3, 4, 5]', '2026-08-16 04:38:30.541255+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('346', 'Governance Infrastructure', '2026-08-16 04:38:42.148399+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down basic approval thresholds — who can spend or commit to what — even if informal for now.", "Recruit one outside advisor to review major decisions, even informally, before formalizing a board.", "Document your three most important recurring decisions and who currently makes them."]', '["all"]', 'INT-346', '24', '[{"name": "RACI Matrix", "brief": "Define who can approve what before oversight gaps turn into real financial or legal exposure."}]', '["RC-821", "RC-818", "RC-816", "RC-820"]', '["RC-820"]', 'Team & Leadership', '[4, 5, 6, 7]', '2026-08-16 04:38:42.148399+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('347', 'Governance Priority Shift', '2026-08-16 04:38:42.148399+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Send one proper investor or stakeholder update this month, even if it feels premature.", "Name any related-party dealing or personal relationship influencing business decisions, even informally to yourself first.", "Notice the next time you skip an approval step because it feels like it will slow you down — name that trade-off explicitly."]', '["all"]', 'INT-347', '24', '[{"name": "Monthly Investor Update Framework", "brief": "Build regular, honest stakeholder reporting so governance becomes routine rather than optional."}]', '["RC-817", "RC-819", "RC-822", "RC-823"]', '["RC-823"]', 'Team & Leadership', '[4, 5, 6, 7]', '2026-08-16 04:38:42.148399+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('348', 'Meeting & Communication Mechanics', '2026-08-16 04:39:05.936968+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Add a written agenda and a clear decision-owner to your next team meeting.", "Document one decision from your last meeting that was never written down anywhere.", "Define one basic communication protocol (which channel for what, expected response time) this week."]', '["all"]', 'INT-348', '25', '[{"name": "RACI Matrix", "brief": "Fix the concrete mechanics of meetings and communication — agendas, ownership, documentation — before addressing deeper culture issues."}]', '["RC-505", "RC-508", "RC-509", "RC-510", "RC-506", "RC-507", "RC-513", "RC-514", "RC-515", "RC-290"]', '["RC-290"]', 'Team & Leadership', '[3, 4, 5, 6]', '2026-08-16 04:39:05.936968+00') on conflict do nothing;
