insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('352', 'Psychological Safety & Leadership Behaviour', '2026-08-16 04:39:05.936968+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next meeting, deliberately ask for disagreement before sharing your own opinion first.", "Notice if your mood is setting the emotional tone of the team on a given day — name it explicitly if so.", "Check one recent action against a stated principle — are they consistent? If not, address the gap directly with the team."]', '["all"]', 'INT-352', '25', '[{"name": "Psychological Safety Framework", "brief": "Build an environment where people can disagree, admit mistakes, and speak honestly without fear."}]', '["RC-295", "RC-512", "RC-258", "RC-259", "RC-289", "RC-286", "RC-249", "RC-511"]', '["RC-511"]', 'Team & Leadership', '[3, 4, 5, 6, 7]', '2026-08-16 04:39:05.936968+00') on conflict do nothing;
