insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('354', 'Feedback, Growth & Sustainable Pace', '2026-08-16 04:39:05.936968+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up one recurring feedback channel (a regular 1:1, a survey) if none currently exists.", "Check your team''s workload against sustainable limits this week — name it if the pace is unsustainable.", "Clarify one role''s expectations that has been ambiguous, in writing, this week."]', '["all"]', 'INT-354', '25', '[{"name": "Psychological Safety Framework", "brief": "Build regular two-way feedback loops so issues surface early instead of accumulating into resignations."}]', '["RC-260", "RC-516", "RC-296", "RC-252", "RC-292", "RC-256"]', '["RC-256"]', 'Team & Leadership', '[3, 4, 5, 6, 7]', '2026-08-16 04:39:05.936968+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('355', 'Investability Fundamentals', '2026-08-16 04:40:47.272526+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["List the three strongest traction proof points you currently have — if they are thin, focus there before pitching more investors.", "Identify the one capability gap on your team that investors are most likely to flag, and address it directly.", "Write one paragraph on your competitive moat — if you cannot defend it, that is the real gap, not the pitch."]', '["all"]', 'INT-355', '26', '[{"name": "Milestone-Based Fundraising Framework", "brief": "Build the traction, team, and moat proof points investors actually need before raising, not just a better pitch."}]', '["RC-297", "RC-301", "RC-303", "RC-307", "RC-304", "RC-298", "RC-305"]', '["RC-305"]', 'Fundraising', '[3, 4, 5]', '2026-08-16 04:40:47.272526+00') on conflict do nothing;
