insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('357', 'Pitch Execution', '2026-08-16 04:40:47.272526+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Prepare your data room fully before your next investor meeting, not after one is requested.", "Write one clear paragraph on exactly how the raised capital will be used.", "List the investors you are targeting and check each one actually invests in your stage and sector."]', '["all"]', 'INT-357', '26', '[{"name": "Sequoia Capital Story Framework", "brief": "Structure the narrative in the order that maximizes investor conviction."}, {"name": "Guy Kawasaki 10-20-30 Rule", "brief": "Simplify the deck so the core story is not lost in detail."}]', '["RC-300", "RC-299", "RC-302", "RC-306", "RC-310"]', '["RC-310"]', 'Fundraising', '[3, 4, 5]', '2026-08-16 04:40:47.272526+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('358', 'Raise Terms Discipline', '2026-08-16 04:40:58.806613+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down the specific milestone this capital is meant to fund — if it is vague, the raise size is probably wrong too.", "Check whether the growth expectations attached to this round are realistic for your actual pace, not investor pace.", "Before accepting a term sheet, calculate how much dilution it costs relative to the value the business has actually proven."]', '["all"]', 'INT-358', '27', '[{"name": "Milestone-Based Fundraising Framework", "brief": "Size the raise to the next real proof point instead of the maximum available or the headline valuation."}]', '["RC-825", "RC-824", "RC-829", "RC-830", "RC-831"]', '["RC-831"]', 'Fundraising', '[2, 3, 4]', '2026-08-16 04:40:58.806613+00') on conflict do nothing;
