insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('361', 'Valuation Emotional Detachment', '2026-08-16 04:41:11.351126+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down where your valuation number actually came from — evidence or how it feels about your effort — and be honest about which.", "Notice if dilution fear is driving you toward a valuation the market will not actually support."]', '["all"]', 'INT-361', '28', '[{"name": "Cognitive Restructuring", "brief": "Separate personal identity and sacrifice from the market-determined value of the business."}]', '["RC-337", "RC-345", "RC-341"]', '["RC-341"]', 'Fundraising', '[3, 4, 5]', '2026-08-16 04:41:11.351126+00') on conflict do nothing;
