insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('484', 'Identity Separation from Outcome', '2026-08-16 09:30:24.659677+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write one sentence completing: this attempt failed at ___. I am not that failure.", "Notice if you are avoiding action because it might not be perfect — check what good enough would actually look like."]', '["all"]', 'INT-484', '123', '[{"name": "Immunity to Change", "brief": "Separate the business outcome from personal identity so failure feels like a decision to learn from, not a verdict on the self."}]', '["RC-517", "RC-527", "RC-519"]', '["RC-519"]', 'Founder Psychology', '[2, 3, 4, 5]', '2026-08-16 09:30:24.659677+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('485', 'Origin Story Reframing', '2026-08-16 09:30:24.659677+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down where your fear of failure was first learned — check if that environment''s rules still apply today.", "Notice if a family expectation is adding pressure to a decision that is actually yours alone to make."]', '["all"]', 'INT-485', '123', '[{"name": "Cognitive Restructuring", "brief": "Separate present-day risk from patterns learned in childhood or from family expectations."}]', '["RC-518", "RC-522", "RC-523"]', '["RC-523"]', 'Founder Psychology', '[2, 3, 4, 5]', '2026-08-16 09:30:24.659677+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('486', 'Judgment & Uncertainty Tolerance', '2026-08-16 09:30:24.659677+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Write down the worst-case outcome of your next decision, then check it against what would realistically happen.", "Notice if you are avoiding a decision because of how it might look to others — check if that concern is proportionate.", "Do one small thing this week specifically to build tolerance for not knowing the outcome in advance."]', '["all"]', 'INT-486', '123', '[{"name": "Premortem Analysis", "brief": "Separate the realistic cost of failure from catastrophic thinking and imagined social judgment."}]', '["RC-528", "RC-520", "RC-526", "RC-524"]', '["RC-524"]', 'Founder Psychology', '[2, 3, 4, 5]', '2026-08-16 09:30:24.659677+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('487', 'Founder Network Access', '2026-08-16 09:30:34.786933+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Reach out to one experienced founder or mentor this week for a regular check-in relationship.", "Join one founder community or peer group where you can speak openly about real challenges."]', '["all"]', 'INT-487', '124', '[{"name": "Failure CV Exercise", "brief": "Actively build access to peers and mentors who understand founder-specific pressure."}]', '["RC-902", "RC-905"]', '["RC-905"]', 'Founder Psychology', '[3, 4, 5, 6, 7]', '2026-08-16 09:30:34.786933+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('488', 'Relational Honesty', '2026-08-16 09:30:34.786933+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Reconnect with one friendship you have let go of since starting the business.", "Notice the reluctance to appear needy in founder spaces — check whether asking for support is actually taking anything from anyone.", "Find one space (not the team) where you can be fully honest about how things are really going."]', '["all"]', 'INT-488', '124', '[{"name": "Cognitive Restructuring", "brief": "Address the belief that asking for support is taking, and rebuild deprioritised relationships."}]', '["RC-903", "RC-904", "RC-907", "RC-906"]', '["RC-906"]', 'Founder Psychology', '[3, 4, 5, 6, 7]', '2026-08-16 09:30:34.786933+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('489', 'Outreach System', '2026-08-16 10:45:25.389772+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Build one reusable outreach template this week that leads with the prospect''s problem, not your product.", "Set up a simple tracker so you know exactly what''s been sent to whom.", "Add at least one follow-up step to your outreach sequence instead of dropping prospects after one message."]', '["all"]', 'INT-489', '157', '[{"name": "Outbound Cadence Design", "brief": "Build a reusable message structure, testing process, and follow-up sequence instead of writing every message from scratch."}]', '["RC-1190", "RC-1192", "RC-1194", "RC-1196", "RC-1193"]', '["RC-1193"]', 'Sales Execution', '[2, 3, 4]', '2026-08-16 10:45:25.389772+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('490', 'Outreach Confidence', '2026-08-16 10:45:25.389772+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Rewrite your next outreach message to make one specific, direct ask instead of a soft, vague one.", "Personalize your next five outreach messages instead of sending the same generic version to everyone."]', '["all"]', 'INT-490', '157', '[{"name": "The Mom Test", "brief": "Write direct, specific outreach instead of vague messaging softened by discomfort with being salesy."}]', '["RC-1191", "RC-1195"]', '["RC-1195"]', 'Sales Execution', '[2, 3, 4]', '2026-08-16 10:45:25.389772+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('491', 'Diagnosing Silence', '2026-08-16 10:45:36.914721+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["In your next follow-up to a quiet prospect, directly ask what changed rather than assuming disinterest.", "Build two different follow-up templates for a soft no versus a hard no.", "Vary your next follow-up message based on the most likely reason for silence, not a single default approach."]', '["all"]', 'INT-491', '190', '[{"name": "SPIN Selling", "brief": "Ask directly why a prospect went quiet instead of assuming, and tailor follow-up to the actual reason."}]', '["RC-1415", "RC-1416", "RC-1417", "RC-1419"]', '["RC-1419"]', 'Sales Execution', '[3, 4, 5]', '2026-08-16 10:45:36.914721+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('492', 'Managing the Silence Reaction', '2026-08-16 10:45:36.914721+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Before writing off a quiet prospect, check whether you are reacting emotionally or deciding deliberately.", "Give one quiet prospect more time than your instinct suggests before giving up."]', '["all"]', 'INT-492', '190', '[{"name": "Cognitive Restructuring", "brief": "Separate the emotional discomfort of silence from a calibrated, deliberate follow-up decision."}]', '["RC-1414", "RC-1418", "RC-1420"]', '["RC-1420"]', 'Sales Execution', '[3, 4, 5]', '2026-08-16 10:45:36.914721+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('493', 'Capturing Real Conversations', '2026-08-16 10:45:48.440695+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Set up one simple shared doc to log every question or objection from sales and support conversations this week.", "Assign someone to review captured questions monthly and turn the best ones into content topics.", "Connect whoever talks to customers with whoever creates content — even a simple weekly share-out."]', '["all"]', 'INT-493', '210', '[{"name": "Continuous Discovery Habits", "brief": "Build a system for capturing sales and support conversations so real customer language becomes usable content material."}]', '["RC-1554", "RC-1555", "RC-1557", "RC-1558"]', '["RC-1558"]', 'Marketing Execution', '[3, 4, 5]', '2026-08-16 10:45:48.440695+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('494', 'Recognizing Content Value', '2026-08-16 10:45:48.440695+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Notice the next question a customer asks for the third time, and turn it directly into a piece of content.", "Before your next content piece, check whether it was inspired by a real conversation or invented in isolation."]', '["all"]', 'INT-494', '210', '[{"name": "Continuous Discovery Habits", "brief": "Recognise recurring customer questions as strong signals for high-value content, rather than guessing topics from scratch."}]', '["RC-1556", "RC-1559", "RC-1560"]', '["RC-1560"]', 'Marketing Execution', '[3, 4, 5]', '2026-08-16 10:45:48.440695+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('495', 'Runway Trend Tracking', '2026-08-16 10:45:59.940648+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Start logging your runway number every time you calculate it, so you can see the trend, not just the latest figure.", "Compare this month''s runway to last month''s explicitly before moving on.", "Set a trigger to investigate whenever runway shifts significantly in either direction."]', '["all"]', 'INT-495', '230', '[{"name": "13-Week Cash Flow Forecast", "brief": "Track runway over time as a trend, not just a single point-in-time number."}]', '["RC-1695", "RC-1694", "RC-1696", "RC-1698"]', '["RC-1698"]', 'Financial Management', '[3, 4, 5, 6]', '2026-08-16 10:45:59.940648+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('496', 'Reading the Underlying Trend', '2026-08-16 10:45:59.940648+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Check whether your current runway, while still positive, has actually been shrinking steadily — treat that trend as the real signal.", "Give the trend direction (improving or worsening) equal weight to the number itself in your next financial review."]', '["all"]', 'INT-496', '230', '[{"name": "Scenario Planning Framework", "brief": "Weight the direction of the trend, not just the current runway figure, since a comfortable number can still be worsening."}]', '["RC-1699", "RC-1697", "RC-1700"]', '["RC-1700"]', 'Financial Management', '[3, 4, 5, 6]', '2026-08-16 10:45:59.940648+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('497', 'SOP Feedback Channel', '2026-08-16 10:46:12.393116+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Create one simple, visible way for anyone to suggest a change to an SOP this week.", "Set a habit of actually updating the SOP when a good suggestion comes in, not just acknowledging it.", "Ask the person doing a task regularly what they''d change about the documented process."]', '["all"]', 'INT-497', '260', '[{"name": "Standard Operating Procedures (SOP) Framework", "brief": "Build an actual channel for suggestions to reach and update the living document, not just live in the team''s heads."}]', '["RC-1906", "RC-1908", "RC-1910", "RC-1912"]', '["RC-1912"]', 'Operations & Systems', '[4, 5, 6]', '2026-08-16 10:46:12.393116+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('498', 'Treating SOPs as Living Documents', '2026-08-16 10:46:12.393116+00', '["minimum_effective_dose", "evidence_based"]', NULL, '["Proactively ask your team this week whether a specific SOP still reflects how work actually gets done.", "Notice if you are treating a written procedure as final — explicitly frame it as a draft that improves over time."]', '["all"]', 'INT-498', '260', '[{"name": "Standard Operating Procedures (SOP) Framework", "brief": "Actively invite feedback on SOPs and treat them as expected to evolve, not fixed once written."}]', '["RC-1907", "RC-1909", "RC-1911"]', '["RC-1911"]', 'Operations & Systems', '[4, 5, 6]', '2026-08-16 10:46:12.393116+00') on conflict do nothing;
insert into "interventions" ("intervention_id", "capability_domain", "created_at", "design_principles", "framework_codes", "immediate_next_steps", "industry_relevance", "intervention_code", "problem_id", "recommended_frameworks", "root_cause_ids", "secondary_root_cause_ids", "section", "stage_relevance", "updated_at") values ('499', 'Explaining the Business', '2026-09-17 12:57:33.014419+00', '["minimum_effective_dose", "evidence_based"]', '["FW-014", "FW-001"]', '["Write the problem you solve in one sentence: who has it, and what changes for them — before you name what you built. Use no word someone outside your field would need explained.", "List the three strongest claims you make about this business, and write beside each one the specific thing outside your own opinion that backs it — a person, a number, a conversation, an order. Mark the ones where you have nothing.", "Explain the business out loud to one person who does not know it, and write down the exact moment they looked lost or asked you to back up.", "Name the single most likely thing someone would do instead of using you — including nothing at all — and write one plain sentence on why they would choose you. Then delete your business name from that sentence and check it could not be anyone else''s."]', '["all"]', 'INT-499', '30', '[{"name": "Obviously Awesome Positioning Framework", "brief": "Define what you do relative to the alternative a specific person would otherwise choose, in their words rather than your category''s."}, {"name": "The Mom Test", "brief": "Get evidence from what people have actually done, not from what they say they would do or think of your idea."}]', '["RC-312", "RC-311", "RC-320", "RC-315", "RC-316", "RC-314"]', '["RC-314"]', 'Fundraising', '[2, 3, 4, 5, 6, 7, 8]', '2026-09-17 13:16:37.284746+00') on conflict do nothing;
